<?php
$rows=db()->query("SELECT oqd.id, o.object_name, d.document_number,d.title,d.status AS doc_status, av.document_date AS assigned_date,av.version_label AS assigned_version, cv.document_date AS current_document_date,cv.version_label AS current_version,cv.change_type AS current_change, oqd.last_checked_at FROM object_qm_documents oqd JOIN objects o ON o.id=oqd.object_id JOIN qm_documents d ON d.id=oqd.document_id JOIN qm_document_versions av ON av.id=oqd.document_version_id LEFT JOIN qm_document_versions cv ON cv.document_id=d.id AND cv.is_current=1 WHERE d.status='aus_qm_entfernt' OR cv.change_type='aus_qm_entfernt' OR oqd.document_version_id<>cv.id ORDER BY o.object_name,d.document_number")->fetchAll();
?>
<div class="panel"><h2>Veraltete Objektordner</h2><p>Diese Übersicht zeigt Objektordner mit veralteten oder aus dem QM entfernten Dokumenten.</p></div>
<div class="panel"><table class="data-table js-data-table"><thead><tr><th>Objekt</th><th>Dokumentnummer</th><th>Dokumentname</th><th>Version im Objektordner</th><th>Aktuelle Version im QM</th><th>Status</th><th>Letzte Prüfung</th><th>Aktion</th></tr></thead><tbody><?php foreach($rows as $r): $status=($r['doc_status']==='aus_qm_entfernt'||$r['current_change']==='aus_qm_entfernt')?'aus QM entfernt':'veraltet'; ?><tr><td><?= e($r['object_name']) ?></td><td><?= e($r['document_number']) ?></td><td><?= e($r['title']) ?></td><td><?= e($r['assigned_date'].' '.$r['assigned_version']) ?></td><td><?= e($r['current_document_date'].' '.$r['current_version']) ?></td><td><?= statusBadge($status) ?></td><td><?= e($r['last_checked_at']) ?></td><td><?php if($status==='veraltet'): ?><form class="ajax-form inline-form" action="ajax/document_control.php" data-reload="outdated_documents" method="post"><?= csrfField() ?><input type="hidden" name="action" value="mark_updated"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button>als aktualisiert markieren</button></form><?php else: ?><span class="muted">aus QM entfernt</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><script>initDataTable('.js-data-table');</script>
